/// </summary>
class METSalesOrderLoadPlanningAidController extends SrsReportRunController
{
    METSalesOrderLoadPlanningAidContract salesLoadPlanningAidContract;
}

Method.Source:
public static METSalesOrderLoadPlanningAidController construct()
{
    return new METSalesOrderLoadPlanningAidController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METSalesOrderLoadPlanningAidController controller = METSalesOrderLoadPlanningAidController::construct();

    controller.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::METCustActivityStatement).getDefaultReportFormat());
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:SOCSalesLoadPlanAid");
    controller.startOperation();
}
